import React, { useEffect, useState, useCallback } from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { useAuth } from '../context/AuthContext';

const Hero = () => {
  const [currentSlide, setCurrentSlide] = useState(0);
  const [isAutoPlaying, setIsAutoPlaying] = useState(true);
  const { settings, API_URL } = useAuth();
  const [slides, setSlides] = useState([]);
  const [loading, setLoading] = useState(true);

  // Default slides fallback
  const defaultSlides = [
    {
      id: 1,
      title: 'We Build Digital Experiences',
      subtitle: 'Creative Solutions',
      description: 'We are a team of passionate developers crafting innovative web solutions for modern businesses.',
      button_text: 'View Portfolio',
      button_link: '#portfolio',
      image_url: null
    }
  ];

  // Fetch slides from API
  useEffect(() => {
    const fetchSlides = async () => {
      try {
        const response = await fetch(`${API_URL}/hero.php`);
        if (response.ok) {
          const data = await response.json();
          const activeSlides = data.filter(slide => slide.is_active !== false);
          setSlides(activeSlides.length > 0 ? activeSlides : defaultSlides);
        } else {
          setSlides(defaultSlides);
        }
      } catch (err) {
        console.error('Error fetching hero slides:', err);
        setSlides(defaultSlides);
      } finally {
        setLoading(false);
      }
    };

    fetchSlides();
  }, [API_URL]);

  const nextSlide = useCallback(() => {
    if (slides.length <= 1) return;
    setCurrentSlide((prev) => (prev + 1) % slides.length);
  }, [slides.length]);

  const prevSlide = useCallback(() => {
    if (slides.length <= 1) return;
    setCurrentSlide((prev) => (prev - 1 + slides.length) % slides.length);
  }, [slides.length]);

  const goToSlide = (index) => {
    setCurrentSlide(index);
  };

  // Auto-play
  useEffect(() => {
    if (!isAutoPlaying || slides.length <= 1) return;
    const interval = setInterval(nextSlide, 5000);
    return () => clearInterval(interval);
  }, [isAutoPlaying, nextSlide, slides.length]);

  const currentSlideData = slides[currentSlide] || defaultSlides[0];

  if (loading) {
    return (
      <section id="home" className="relative h-screen bg-[#0a1628]">
        <div className="absolute inset-0 flex items-center justify-center">
          <div className="animate-pulse text-blue-500">Loading...</div>
        </div>
      </section>
    );
  }

  return (
    <section id="home" className="relative h-screen overflow-hidden bg-[#0a1628]">
      {/* Main Background Image */}
      <div className="absolute inset-0">
        {slides.map((slide, index) => (
          <div
            key={slide.id}
            className={`absolute inset-0 transition-opacity duration-700 ease-in-out ${
              index === currentSlide ? 'opacity-100' : 'opacity-0'
            }`}
          >
            {slide.image_url ? (
              <img
                src={slide.image_url}
                alt={slide.title}
                className="w-full h-full object-cover"
              />
            ) : (
              <div className="w-full h-full bg-gradient-to-br from-[#0a1628] via-[#1e293b] to-[#0a1628]" />
            )}
            {/* Dark Overlay */}
            <div className="absolute inset-0 bg-black/50" />
          </div>
        ))}
      </div>

      {/* Content Overlay */}
      <div className="absolute inset-0 flex flex-col justify-center px-8 md:px-16 lg:px-24 z-10">
        <div className="max-w-2xl">
          {/* Subtitle */}
          {currentSlideData.subtitle && (
            <p className="text-blue-400 text-lg md:text-xl mb-4 font-medium tracking-wide">
              {currentSlideData.subtitle}
            </p>
          )}

          {/* Title */}
          <h1 className="text-4xl md:text-6xl lg:text-7xl font-bold text-white mb-6 leading-tight">
            {currentSlideData.title}
          </h1>

          {/* Description */}
          <p className="text-gray-300 text-base md:text-lg mb-8 max-w-xl leading-relaxed">
            {currentSlideData.description}
          </p>

          {/* CTA Button */}
          <a
            href={currentSlideData.button_link || '#portfolio'}
            className="inline-block px-8 py-3 bg-white text-black font-semibold rounded-full hover:bg-gray-200 transition-colors"
          >
            {currentSlideData.button_text || 'Learn More'}
          </a>
        </div>
      </div>

      {/* Thumbnail Carousel at Bottom */}
      {slides.length > 1 && (
        <div className="absolute bottom-8 left-1/2 -translate-x-1/2 z-20">
          <div className="flex items-center gap-3 bg-black/40 backdrop-blur-md rounded-2xl p-3 border border-white/10">
            {slides.map((slide, index) => (
              <button
                key={slide.id}
                onClick={() => goToSlide(index)}
                className={`relative rounded-xl overflow-hidden transition-all duration-300 ${
                  index === currentSlide
                    ? 'ring-2 ring-white scale-105'
                    : 'opacity-60 hover:opacity-80'
                }`}
                style={{ width: '80px', height: '100px' }}
                aria-label={`Go to slide ${index + 1}`}
              >
                {slide.image_url ? (
                  <img
                    src={slide.image_url}
                    alt={slide.title}
                    className="w-full h-full object-cover"
                  />
                ) : (
                  <div className="w-full h-full bg-gradient-to-br from-gray-700 to-gray-800" />
                )}
                {/* Label overlay */}
                <div className="absolute inset-x-0 bottom-0 bg-black/60 py-1 px-2">
                  <p className="text-white text-xs truncate">{slide.title?.slice(0, 8) || `Slide ${index + 1}`}</p>
                </div>
              </button>
            ))}
          </div>
        </div>
      )}
    </section>
  );
};

export default Hero;
